def project(p): return (p/"app.py").is_file() and (p/"src").is_dir() and (p/"requirements.txt").is_file()
def choose():
 b=Path(__file__).resolve().parent; out=[]
 for p in (b,b/"company-knowledge-search",Path.cwd(),Path.cwd()/"company-knowledge-search"):
  p=p.resolve()
  if project(p) and p not in out:out.append(p)
